/**
 * Boing Express provider — runs in the page context (injected by content script).
 * Exposes window.boing for dApps. Prefer Boing-native methods (no dependency on Ethereum naming):
 *
 *   boing_requestAccounts  — connect and get current account
 *   boing_accounts        — get account if site already connected
 *   boing_signMessage        — sign hex message (e.g. for auth)
 *   boing_signTransaction    — sign native Boing tx; params: [txObject]; returns 0x + hex(bincode SignedTransaction). Types include transfer, bond, unbond, claim_unbond, qa_pool_vote, contract_call, contract_deploy_purpose / contract_deploy_meta. QA pool votes: type qa_pool_vote, subject (32-byte pending deploy tx hash), vote allow|reject|abstain. Deploy: include bincode create2_salt (Option 32 bytes); pass create2_salt as 64 hex chars for CREATE2, or omit for nonce-derived address. contract_deploy_meta defaults purpose_category to "token" when asset_name or asset_symbol is set. contract_call: use 32-byte `contract`, `calldata`, and `access_list` { read, write } (hex AccountIds) per boing-sdk / RPC-API-SPEC; when access_list is omitted, the wallet fills the protocol suggested list for transfer/bond/unbond/claim_unbond/qa_pool_vote/contract_call.
 *   boing_sendTransaction    — sign + simulate + submit; params: [txObject]; returns tx hash string (mempool QA still runs on deploy). On simulation failure, error.data may include suggested_access_list + access_list_covers_suggestion for retry.
 *   boing_simulateTransaction — params: [hexSignedTx]; forwards to node RPC (no extra signing). Connected origin required.
 *   boing_simulateContractCall — params: [contractHex, calldataHex, senderHex?, atBlock?]; unsigned contract_call dry-run per RPC-API-SPEC. Connected origin required. If senderHex is omitted, the active vault account is sent as the third RPC param when available.
 *   boing_listDexPools / boing_listDexTokens / boing_getDexToken — L1 DEX discovery; params mirror boing-sdk (single object in params array). Connected origin required. See docs/BOING-EXPRESS-WALLET.md.
 *   boing_getCapabilities - { version, features }, answered in the page; features has 'nativeValue' when contract calls may carry `value` (0.1.19+), 'priorityTip' when `priority_tip` is signed (0.1.21+), and 'putBlobSession' when `boing_requestPutBlobSession` is available (0.1.22+). Also exposed as provider.version / provider.features.
 *   boing_requestPutBlobSession — one approval covering many subsequent put_blob sends (params: [{ maxBlobs, maxTotalBytes?, maxBytesPerBlob?, ttlMs? }]).
 *   boing_getPutBlobSession / boing_endPutBlobSession — inspect or clear the origin's PutBlob publish session.
 *   boing_chainId           — current chain (0x1b01 testnet, 0x1b02 mainnet)
 *   boing_switchChain       — switch network
 *
 * Aliases eth_requestAccounts, eth_accounts, personal_sign, eth_chainId, wallet_switchEthereumChain
 * are supported for compatibility but are not required for Boing development.
 */

declare const __BOING_EXPRESS_VERSION__: string;
/** Injected at build time from extension/manifest.base.json (vite.extension.inpage.config.ts). */
const BOING_EXPRESS_VERSION: string = typeof __BOING_EXPRESS_VERSION__ === 'string' ? __BOING_EXPRESS_VERSION__ : '0.0.0';
const BOING_EXPRESS_FEATURES: readonly string[] = Object.freeze([
  'nativeValue',
  'priorityTip',
  'putBlobSession',
]);

const BOING_PROVIDER_SOURCE = 'boing-inpage';
const BOING_CONTENT_SOURCE = 'boing-content';

let nextId = 1;
const pending = new Map<number, { resolve: (v: unknown) => void; reject: (e: Error) => void }>();

type SerializedProviderError = {
  code?: number;
  message?: string;
  data?: unknown;
};

const APPROVAL_METHODS = new Set([
  'boing_requestAccounts',
  'boing_signMessage',
  'boing_signTransaction',
  'boing_sendTransaction',
  'boing_requestPutBlobSession',
  'eth_requestAccounts',
  'personal_sign',
]);

function sendToExtension(method: string, params: unknown[]): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const id = nextId++;
    pending.set(id, { resolve, reject });
    window.postMessage(
      {
        source: BOING_PROVIDER_SOURCE,
        type: 'request',
        id,
        method,
        params,
      },
      '*'
    );
    // Approval flows need longer than a silent RPC; keep a bound so dead content scripts don't hang forever.
    const timeoutMs = APPROVAL_METHODS.has(method) ? 3 * 60 * 1000 : 60_000;
    setTimeout(() => {
      if (pending.has(id)) {
        pending.delete(id);
        reject(new Error('Boing Express: request timed out'));
      }
    }, timeoutMs);
  });
}

function createProviderError(error: unknown): Error & { code?: number; data?: unknown } {
  if (error && typeof error === 'object') {
    const serialized = error as SerializedProviderError;
    const wrapped = new Error(serialized.message ?? 'Boing Express request failed') as Error & {
      code?: number;
      data?: unknown;
    };
    wrapped.code = serialized.code;
    wrapped.data = serialized.data;
    return wrapped;
  }
  return new Error(typeof error === 'string' ? error : 'Boing Express request failed');
}

function createProvider(): unknown {
  const listeners: Record<string, Array<(...args: unknown[]) => void>> = {
    message: [],
    connect: [],
    disconnect: [],
    chainChanged: [],
    accountsChanged: [],
  };

  const provider = {
    isBoing: true,
    isBoingExpress: true,
    /** True for Boing Express — aligns with boing-sdk `providerSupportsBoingNativeRpc` / connectInjectedBoingWallet. */
    supportsBoingNativeRpc: true,
    /** Extension version (from the manifest), e.g. `0.1.19`. Absent on 0.1.18 and older. */
    version: BOING_EXPRESS_VERSION,
    /**
     * Capability flags.
     * - `nativeValue`: `value` on `contract_call` / batch steps is signed as ContractCallWithValue.
     * - `priorityTip` (0.1.21+): `priority_tip` / `priorityTip` on dApp JSON is bound into the signature.
     * - `putBlobSession` (0.1.22+): `boing_requestPutBlobSession` — one approval for many PutBlob publishes.
     * Wallets without a flag drop that field silently — dApps should check before relying on it.
     */
    features: BOING_EXPRESS_FEATURES,

    request(args: { method: string; params?: unknown[] }): Promise<unknown> {
      const method = args?.method;
      const params = Array.isArray(args?.params) ? args.params : [];
      // Answered in the page (no wallet round trip): what this wallet build can sign.
      if (method === 'boing_getCapabilities') {
        return Promise.resolve({ version: BOING_EXPRESS_VERSION, features: [...BOING_EXPRESS_FEATURES] });
      }
      return sendToExtension(method, params);
    },

    on(event: string, listener: (...args: unknown[]) => void): void {
      if (listeners[event]) listeners[event].push(listener);
    },

    removeListener(event: string, listener: (...args: unknown[]) => void): void {
      if (listeners[event]) {
        const i = listeners[event].indexOf(listener);
        if (i !== -1) listeners[event].splice(i, 1);
      }
    },

    emit(event: string, ...args: unknown[]): void {
      (listeners[event] || []).slice().forEach((fn) => {
        try {
          fn(...args);
        } catch (_) {}
      });
    },
  };

  return provider;
}

const provider = createProvider();
const eip6963Info = Object.freeze({
  uuid: 'boing-express-6963',
  name: 'Boing Express',
  icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg"/>',
  rdns: 'express.boing',
});

function announceEip6963Provider(): void {
  const event = new CustomEvent('eip6963:announceProvider', {
    detail: Object.freeze({ info: eip6963Info, provider }),
  });
  window.dispatchEvent(event);
}

window.addEventListener('message', (event: MessageEvent) => {
  if (event.source !== window || !event.data || event.data.source !== BOING_CONTENT_SOURCE) return;
  const { type, id, result, error, event: eventName, payload } = event.data;
  if (type === 'response' && id != null) {
    const p = pending.get(id);
    if (!p) return;
    pending.delete(id);
    if (error != null) {
      p.reject(createProviderError(error));
    } else {
      p.resolve(result);
    }
    return;
  }

  if (type === 'event' && typeof eventName === 'string') {
    const emitter = provider as { emit: (event: string, ...args: unknown[]) => void };
    if (eventName === 'accountsChanged') {
      emitter.emit(eventName, Array.isArray(payload?.accounts) ? payload.accounts : []);
      return;
    }
    if (eventName === 'chainChanged') {
      emitter.emit(eventName, typeof payload?.chainId === 'string' ? payload.chainId : undefined);
      return;
    }
    if (eventName === 'disconnect') {
      emitter.emit(eventName, payload);
      return;
    }
    emitter.emit(eventName, payload);
  }
});

// Expose on window for dApps. Use a symbol-like key to avoid clashes; dApps can detect window.boing.
(globalThis as unknown as { boing?: unknown }).boing = provider;

// EIP-6963: announce provider so dApps can discover multiple wallets (optional but improves compatibility)
try {
  window.addEventListener('eip6963:requestProvider', announceEip6963Provider);
  announceEip6963Provider();
} catch (_) {}
